import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Typography, Button, CircularProgress } from "@mui/material";
import { supabase } from "../supabase";

const VerifyPage = () => {
  const [status, setStatus] = useState("checking");
  const navigate = useNavigate();

  useEffect(() => {
    const checkVerification = async () => {
      try {
        // Step 1: Get session from URL
        const { error: urlError } = await supabase.auth.getSessionFromUrl({ storeSession: true });
        if (urlError) {
          console.error("URL session error:", urlError.message);
          setStatus("failed");
          return;
        }

        // Step 2: Give Supabase a moment to finalize session
        await new Promise((res) => setTimeout(res, 1000));

        // Step 3: Check if user is confirmed
        const { data: userData, error: userError } = await supabase.auth.getUser();
        if (userError || !userData?.user) {
          console.error("User fetch failed:", userError?.message);
          setStatus("failed");
          return;
        }

        const isConfirmed = userData.user.confirmed_at !== null;
        setStatus(isConfirmed ? "verified" : "pending");
      } catch (err) {
        console.error("Unexpected error:", err);
        setStatus("failed");
      }
    };

    checkVerification();
  }, []);

  return (
    <Box sx={{ textAlign: "center", mt: 10 }}>
      {status === "checking" && (
        <>
          <CircularProgress />
          <Typography mt={2}>Checking verification status...</Typography>
        </>
      )}
      {status === "verified" && (
        <>
          <Typography variant="h5" color="green">✅ Email verified!</Typography>
          <Button sx={{ mt: 2, backgroundColor: "#8E2839" }} onClick={() => navigate("/signin")}>
            Go to Sign In
          </Button>
        </>
      )}
      {status === "pending" && (
        <>
          <Typography color="orange">⚠️ Email not verified yet.</Typography>
          <Typography>Check your inbox for the verification link.</Typography>
          <Button variant="outlined" sx={{ mt: 2 }} onClick={() => window.location.reload()}>
            Retry
          </Button>
        </>
      )}
      {status === "failed" && (
        <>
          <Typography color="red">❌ Unable to verify your account.</Typography>
          <Typography>Make sure you're logged in and used the same browser.</Typography>
          <Button sx={{ mt: 2, backgroundColor: "#8E2839" }} onClick={() => navigate("/signin")}>
            Back to Sign In
          </Button>
        </>
      )}
    </Box>
  );
};

export default VerifyPage;
